#!/usr/bin/env node
/**
 * save-snapshots — STS2 Companion's save test data, generated by the REAL Rust projection.
 *
 *   node scripts/sts2/save-snapshots.mjs
 *
 * Runs dissent-client's ignored `write_plugin_snapshots` test over the scrubbed fixtures in
 * dissent-client/src-tauri/tests/fixtures/sts2/, copies what it writes into fixtures/saves/, and
 * records the sha256 of every source. save-snapshots.test.mjs fails when any source changes, so a
 * projection change can never leave the plugin tested against an answer the app no longer gives.
 *
 * 🔴 Never hand-edit fixtures/saves/. Rerun this.
 */
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, writeFileSync, mkdirSync, readdirSync, copyFileSync, rmSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

export const MONOREPO = process.env.DISSENT_MONOREPO ?? '/home/ubuntu/projects';
const FIX = 'dissent-client/src-tauri/tests/fixtures/sts2';
export const SOURCES = [
  'dissent-client/src-tauri/src/game_saves/sts2/project.rs',
  'dissent-client/src-tauri/src/game_saves/sts2/mod.rs',
  `${FIX}/current_run_entering_first_combat.save`,
  `${FIX}/current_run_after_first_combat.save`,
  `${FIX}/finished_coop_loss.run`,
  `${FIX}/progress.save`,
];
export const sha256 = (rel) => createHash('sha256').update(readFileSync(join(MONOREPO, rel))).digest('hex');

function main() {
  const out = fileURLToPath(new URL('./fixtures/saves/', import.meta.url));
  const tmp = mkdtempSync(join(tmpdir(), 'sts2-snapshots-'));
  execFileSync('cargo', ['test', '--lib', 'write_plugin_snapshots', '--', '--ignored'], {
    cwd: join(MONOREPO, 'dissent-client/src-tauri'),
    env: { ...process.env, STS2_SNAPSHOT_OUT: tmp },
    stdio: 'inherit',
  });
  const files = readdirSync(tmp).filter((f) => f.endsWith('.json'));
  if (files.length !== 5) throw new Error(`expected 5 snapshots, got ${files.join(', ')}`);
  rmSync(out, { recursive: true, force: true });
  mkdirSync(out, { recursive: true });
  for (const f of files) copyFileSync(join(tmp, f), join(out, f));
  rmSync(tmp, { recursive: true, force: true });
  const provenance = { note: 'Generated by scripts/sts2/save-snapshots.mjs. Do not edit.', sources: Object.fromEntries(SOURCES.map((p) => [p, sha256(p)])) };
  writeFileSync(join(out, 'provenance.json'), `${JSON.stringify(provenance, null, 2)}\n`);
  console.log(`save-snapshots: ${files.length} snapshots → ${out}`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
